use relay.feed;

fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var total = 0;
    for frame in relay.feed.received() {
        total = total + match relay.feed.decode(frame) {
            Some(value) => value,
            None => 0,
        };
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let frame = frames.get(index: i);
        total = total + match relay.feed.decode(frame) {
            Ok(value) => value,
            Err(_) => 0,
        };
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

