use galley.menu.{board};
use galley.kitchen.{serve};

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let dishes = board();
    var i = 0;
    while i < dishes.len() {
        if i > 0 {
            io.write(text: ";")?;
        }
        serve(dish: dishes[i], io: io)?;
        i = i + 1;
    }
    return Ok(unit);
}

