use mill.stock;
use mill.rules;

fn lines() -> String {
    let planks = stock.planks();
    var out = "";
    var first = true;
    var i = 0;
    while i < planks.len() {
        let plank = planks.get(i);
        if rules.keep(plank) {
            let label = rules.label(plank);
            if first {
                out = label;
                first = false;
            } else {
                out = out.concat(other: ",").concat(other: label);
            }
        }
        i = i + 1;
    }
    out
}

